package com.wutong.wtlyf.license.unbinder;
import android.app.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import org.json.*;
public final class MainActivity extends Activity{private static final String BASE="https://wtlyf-license-center.creamy-bowl-8571.chatgpt.site/api/admin/";private EditText token,code;private TextView status;
@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=base();TextView title=text("wtlyf 卡密解绑",30,Color.WHITE);title.setTypeface(null,1);root.addView(title);root.addView(text("查询绑定状态 · 一键释放设备",14,Color.rgb(143,174,207)));root.addView(space(28));LinearLayout card=card();token=input("管理员令牌");token.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);card.addView(token);code=input("WTLYF-XXXXX-XXXXX-XXXXX-XXXXX");card.addView(code);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button query=button("查询状态",Color.rgb(49,94,155));Button unbind=button("解除绑定",Color.rgb(165,50,91));row.addView(query,new LinearLayout.LayoutParams(0,-2,1));row.addView(unbind,new LinearLayout.LayoutParams(0,-2,1));card.addView(row);status=text("等待操作",14,Color.rgb(133,185,255));status.setTextIsSelectable(true);card.addView(status);root.addView(card);query.setOnClickListener(v->request("status",query));unbind.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("确认解绑").setMessage("解绑后该卡密可被其他设备重新激活。").setNegativeButton("取消",null).setPositiveButton("确认解绑",(d,w)->request("unbind",unbind)).show());setContentView(scroll(root));}
private void request(String action,Button btn){btn.setEnabled(false);status.setText("正在处理…");new Thread(()->{try{JSONObject r=post(action,new JSONObject().put("code",code.getText().toString().trim().toUpperCase()),token.getText().toString());runOnUiThread(()->{status.setText(r.optBoolean("ok")?(r.has("license")?r.optJSONObject("license").toString():r.optString("message","操作成功")):r.optString("message","操作失败"));btn.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("请求失败："+e.getMessage());btn.setEnabled(true);});}},"license-unbinder").start();}
private JSONObject post(String p,JSONObject body,String key)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(BASE+p).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+key.trim());c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}InputStream in=c.getResponseCode()>=400?c.getErrorStream():c.getInputStream();StringBuilder s=new StringBuilder();if(in!=null)try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){for(String l;(l=r.readLine())!=null;)s.append(l);}return new JSONObject(s.length()==0?"{}":s.toString());}
private LinearLayout base(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(28,60,28,40);l.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(5,11,27),Color.rgb(14,29,57),Color.rgb(29,18,60)}));return l;}private LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,24,24,24);l.setBackground(round(Color.argb(205,15,29,55),26));return l;}private EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setHintTextColor(Color.rgb(116,143,174));e.setTextColor(Color.WHITE);e.setBackground(round(Color.argb(150,2,10,25),16));e.setPadding(18,16,18,16);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,14);e.setLayoutParams(p);return e;}private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setBackground(round(c,18));return b;}private TextView text(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(0,10,0,10);return v;}private Space space(int h){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,h));return s;}private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);d.setStroke(1,Color.argb(80,130,210,255));return d;}private ScrollView scroll(LinearLayout l){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(l);return s;}}

